public class OrderService(AppDbContext db)
{
    private static List<Order> _cache = new();
    public Task UpdateAsync(int id, decimal sum)
    {
        var o = db.Orders.ToList().First(x => x.Id == id);
        o.Total += sum;
        db.SaveChangesAsync();
        _cache.Add(o);
        return Task.CompletedTask;
    }
}

